const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${({watch:'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="m8 22 4-4 4 4M8 10h8M12 6v8"/>',waivers:'<path d="m3 17 6-6 4 3 8-10M15 4h6v6"/>',lineup:'<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>',trades:'<path d="M3 7h18m-5-5 5 5-5 5M21 17H3m5-5-5 5 5 5"/>',defenses:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/>',settings:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>'})[name]}</svg>`;
const nav=[['watch','Sunday watchroom'],['waivers','Waiver wire'],['lineup','Start / sit'],['trades','Trade lab'],['defenses','Defense planner'],['settings','My leagues']];
import {demo} from './demo.js';
import * as api from './api.js';
import {activeSlots,eligible,projected,optimize,availableIds,playableIds,aggregateWatch,tradeResult} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=1)=>Number.isFinite(n)?(Math.abs(n)<Math.pow(10,-d)/2?0:n).toFixed(d):'—',signed=n=>`${n>0?'+':''}${fmt(n)}`;
const colors=['#aebee8','#e4ba6f','#82b9a7','#b89bc7','#92b9da'];
const teamColors={CIN:'#d96527',BUF:'#2761a4',ATL:'#a3434c',MIN:'#7460a3',LV:'#64747a',DET:'#2980a4',KC:'#b94340',PHI:'#27675c',BAL:'#70659c',SF:'#ab4744',DAL:'#4b7195',NYJ:'#387565',GB:'#376c51',LAR:'#3876bb',HOU:'#365e79',MIA:'#298e92'};
let data=demo(),view='watch',filter='all',query='',watchRole='both',bench=false,leagueId='demo-0',watchLeague='all',position='ALL',focus=false,busy=false,partnerId='2',give=[],get=[],penalty=.15,requireBenefit=true,tradeSuggestions=null,tradeManual=null,connectRun=0;
let prefs;try{prefs=JSON.parse(localStorage.getItem('sunday-preferences')||'{}')}catch{prefs={}}let pins=new Set(prefs.pins||[]);
function savePrefs(){try{localStorage.setItem('sunday-preferences',JSON.stringify({...prefs,pins:[...pins],disabled:data.demo?(prefs.disabled||[]):data.leagues.filter(l=>!l.enabled).map(l=>l.league_id)}))}catch{toast('Browser storage is unavailable; preferences will reset when you close this page.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500)}
const league=()=>data.leagues.find(l=>l.league_id===leagueId&&l.enabled)||data.leagues.find(l=>l.enabled);
const pname=id=>data.players[id]?.full_name||[data.players[id]?.first_name,data.players[id]?.last_name].filter(Boolean).join(' ')||id||'Empty slot';
function value(id,l=league(),w=data.week){return projected(data.projections[w]?.[id]?.stats,l?.scoring_settings)}
const scoring=l=>l.scoring_settings?.rec===1?'PPR':l.scoring_settings?.rec===.5?'HALF PPR':l.scoring_settings?.rec===0||!l.scoring_settings?.rec?'STANDARD':'CUSTOM';
function leagueOptions(selected=leagueId,all=false){return (all?'<option value="all">All leagues</option>':'')+data.leagues.filter(l=>l.enabled).map(l=>`<option value="${esc(l.league_id)}" ${selected===l.league_id?'selected':''}>${esc(l.name)}</option>`).join('')}
function empty(title,body=''){return `<div class="empty"><h3>${esc(title)}</h3>${body?`<p>${esc(body)}</p>`:''}</div>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${data.demo?'EXPLORE THE DEMO':esc(data.user.username)+'’S PLAYBOOK'} · WEEK ${data.week}</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`}
function projectionNote(){const l=league();let missing=[];if(l){const keys=new Set(Object.values(data.projections[data.week]||{}).flatMap(p=>Object.keys(p.stats||{})));missing=Object.entries(l.scoring_settings||{}).filter(([k,v])=>v!==0&&!keys.has(k)).map(([k])=>k)}return `<div class="note ${Object.keys(data.projections[data.week]||{}).length?'':'warn'}">${data.demo?'Sample projections for exploring the prototype.':Object.keys(data.projections[data.week]||{}).length?'Experimental Sleeper projections, converted using this league’s scoring. Estimates are not guarantees; projected bonuses may be incomplete.':'Projections are unavailable for this week. Scores and rosters still work; recommendations requiring projections are paused.'}${missing.length?` <strong>Unmodeled scoring: ${esc(missing.join(', '))}.</strong>`:''}</div>`}
function analysisHeader(title,desc){return pageHead(title,desc,`<select class="select" aria-label="Analysis league" id="analysis-league">${leagueOptions(league()?.league_id)}</select>`)+projectionNote()}
function render(){const active=document.activeElement,keep=active?.id,sel=active?.selectionStart;
 document.body.classList.toggle('focus',focus&&view==='watch');
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand">sunday<em>／</em><small>HQ</small></div><div class="nav-label">YOUR PLAYBOOK</div><nav aria-label="Main navigation">${nav.map(([id,label])=>`<button class="nav-btn ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><p>Less switching.<br>More football.</p><button class="nav-btn" data-nav="settings">${icon('settings')}${data.leagues.filter(l=>l.enabled).length} leagues connected</button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">sunday／</div><div class="crumb">Fantasy football <span style="margin:0 10px">/</span> <strong>${nav.find(x=>x[0]===view)[1]}</strong></div><div class="top-actions"><span class="pill ${data.demo?'demo':''}">${data.demo?'DEMO MODE':'SLEEPER CONNECTED'}</span><button class="primary" data-connect>${data.demo?'Connect Sleeper ↗':esc(data.user.username)}</button></div></header><div class="content">${data.errors.length?`<div class="note warn" role="status">${data.errors.map(esc).join(' · ')}</div>`:''}${view!=='settings'&&!data.leagues.some(l=>l.enabled)?empty('No leagues selected','Open My leagues to include a league in your dashboard.'):({watch:watchroom,waivers:waivers,lineup:lineup,trades:trades,defenses:defenses,settings:settings})[view]()}<footer class="status-footer"><span>${data.demo?'Illustrative demo · sample scores':`Updated ${new Date(data.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit',second:'2-digit'})} · refreshes every 45 seconds while visible`}</span><span><a href="https://docs.sleeper.com/" target="_blank" rel="noopener">Sleeper data & trends</a> · NFL game status: ESPN</span></footer></div></main>`;
 if(keep){const el=document.getElementById(keep);if(el){el.focus({preventScroll:true});if(typeof sel==='number'&&el.setSelectionRange){try{el.setSelectionRange(sel,sel)}catch{}}}}
}
function leagueCards(){return `<div class="league-grid">${data.leagues.filter(l=>l.enabled).map((l,i)=>{const m=l.matchups.find(m=>m.roster_id===l.mine.roster_id),opp=m?.matchup_id==null?null:l.matchups.find(x=>x.matchup_id===m.matchup_id&&x.roster_id!==m.roster_id),r=l.rosters.find(r=>r.roster_id===opp?.roster_id),user=l.users.find(u=>u.user_id===r?.owner_id),playing=(m?.starters||l.mine.starters||[]).filter(id=>data.games[data.players[id]?.team]?.state==='in').length;return `<article class="league-card" style="--league:${colors[i%colors.length]}"><div class="league-title"><span>${esc(l.name)}</span><small>${scoring(l)}</small></div><div class="match-score"><strong>${fmt(m?.custom_points??m?.points,2)}</strong><span>vs</span><strong class="opponent">${fmt(opp?.custom_points??opp?.points,2)}</strong></div><div class="league-foot"><span>vs ${esc(user?.metadata?.team_name||user?.display_name||'No matchup yet')}</span><span>${playing} in live games</span></div></article>`}).join('')}</div>`}
function watchroom(){return pageHead('Sunday watchroom','Follow the players that matter. Across every league.',`<button class="secondary" id="focus">⛶ ${focus?'Exit focus mode':'Focus mode'}</button>`)+leagueCards()+`<div class="section-bar"><h2>Your game day <span class="count" id="player-count"></span></h2><div class="filters"><select class="week-selector" aria-label="NFL week" id="week">${Array.from({length:18},(_,i)=>`<option value="${i+1}" ${data.week===i+1?'selected':''}>Week ${i+1}</option>`).join('')}</select><button class="secondary" id="refresh" ${busy?'disabled':''}>${busy?'Refreshing…':'↻ Refresh'}</button></div></div><div class="toolbar"><div class="filters">${[['all','All players'],['live','Playing now'],['upcoming','Up next'],['done','Final'],['pinned','Pinned']].map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><input class="search" id="search" value="${esc(query)}" placeholder="Find a player or NFL team…" aria-label="Search players"></div><div class="section-bar"><div class="filters"><select class="select" aria-label="Watchroom league" id="watch-league">${leagueOptions(watchLeague,true)}</select><select class="select" id="watch-role" aria-label="Players to follow">${[['both','My players + opponents'],['mine','My players only'],['opponent','Opponents only']].map(([v,t])=>`<option value="${v}" ${watchRole===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" id="bench" ${bench?'checked':''}>Include my bench</label></div><div class="watch-grid" id="players">${watchCards()}</div><p class="muted small" style="margin-top:18px">“Game live” means the player’s NFL game is in progress, not that they’re on the field. Scores can differ by league.</p>`}
function watchCards(){const pool=aggregateWatch(data.leagues,data.players,data.games);if(filter==='pinned'){for(const id of pins){if(data.players[id]&&!pool.some(p=>p.id===id))pool.push({id,player:data.players[id],game:data.games[data.players[id].team],appearances:data.leagues.filter(l=>l.enabled).map(l=>({leagueId:l.league_id,league:l.name,side:'watch',starter:true,points:value(id,l),prediction:true}))})}}let cards=pool.map(p=>({...p,appearances:p.appearances.filter(a=>(watchLeague==='all'||a.leagueId===watchLeague)&&(watchRole==='both'||a.side===watchRole||a.side==='watch')&&(a.starter||bench))})).filter(p=>p.appearances.length).filter(p=>(filter==='all'||filter==='pinned'&&pins.has(p.id)||filter==='live'&&p.game?.state==='in'||filter==='upcoming'&&p.game?.state==='pre'||filter==='done'&&p.game?.state==='post')&&`${pname(p.id)} ${p.player.team} ${p.player.number||''} ${p.player.position}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(pins.has(b.id)-pins.has(a.id))||({in:0,pre:1,post:2}[a.game?.state]??3)-({in:0,pre:1,post:2}[b.game?.state]??3)||pname(a.id).localeCompare(pname(b.id)));
 queueMicrotask(()=>{if($('#player-count'))$('#player-count').textContent=cards.length});
 return cards.map(({id,player:p,game:g,appearances})=>{const state=g?.state,live=state==='in',label=live?'GAME LIVE':state==='pre'?'UP NEXT':state==='post'?'FINAL':'NO GAME DATA';return `<article class="player-card" style="--team:${teamColors[p.team]||'#567587'}"><div class="player-top"><span class="pill ${live?'live':''}">${label}</span><span>${esc(g?.detail||'Schedule unavailable')}</span></div><div class="player-main"><div class="jersey">${esc(p.number??(p.position==='DEF'?'D':'—'))}</div><div><div class="player-name">${esc(pname(id))}</div><div class="player-meta">${esc(p.team||'FA')} · ${esc(p.position)}${p.number!=null?' · #'+esc(p.number):''}${p.injury_status?` · <strong class="attention">${esc(p.injury_status)}</strong>`:''}</div></div></div><div class="player-stat">${g?`${esc(p.team)} ${g.home?'vs':'@'} ${esc(g.opponent)}${state!=='pre'?` · ${esc(g.score)}–${esc(g.oppScore)}`:''}${g.channel?' · '+esc(g.channel):''}`:'NFL schedule not available'}</div>${appearances.map(a=>`<div class="score-row"><span><span class="tag ${a.side==='opponent'?'against':''}">${a.side==='opponent'?'AGAINST':a.side==='watch'?'WATCH':a.starter?'STARTER':'BENCH'}</span>${esc(a.league)}</span><strong title="${esc(a.league)} fantasy points">${fmt(a.points,2)}${a.prediction?' <small>proj</small>':''}</strong></div>`).join('')}<div class="player-bottom"><span>${new Set(appearances.map(a=>a.leagueId)).size} league${new Set(appearances.map(a=>a.leagueId)).size===1?'':'s'} · ${data.demo?'sample':'Sleeper'} points</span><button class="pin ${pins.has(id)?'on':''}" data-pin="${esc(id)}" aria-label="${pins.has(id)?'Unpin':'Pin'} ${esc(pname(id))}" aria-pressed="${pins.has(id)}">${pins.has(id)?'★':'☆'}</button></div></article>`}).join('')||empty('No players in this view',filter==='live'?'No tracked games are live right now. Try All players or Up next.':'Try another filter or include your bench.');}
function lockedLineup(l){const m=l.matchups.find(m=>m.roster_id===l.mine.roster_id);const ids=m?.starters||l.mine.starters||[];const locks={};ids.forEach((id,i)=>{const g=data.games[data.players[id]?.team];if(id&&id!=='0'&&g&&g.state!=='pre')locks[i]=id});return {ids,locks};}
function usableValue(id,l,lockedIds=[]){const p=data.players[id];if(['Out','IR','Suspended','PUP','Doubtful'].includes(p?.injury_status)&&!lockedIds.includes(id))return null;const g=data.games[p?.team];if(g&&g.state!=='pre'&&!lockedIds.includes(id))return null;return value(id,l);}
function lineup(){const l=league(),slots=activeSlots(l),{ids,locks}=lockedLineup(l),fixed=Object.values(locks),v=id=>usableValue(id,l,fixed);let best;try{best=optimize(playableIds(l.mine),slots,data.players,v,locks)}catch(e){return analysisHeader('Start / sit','Your best legal lineup, with room for a late swap.')+empty(e.message)}const baseline=ids.reduce((s,id)=>s+(v(id)??0),0),complete=best.complete&&ids.every(id=>id==='0'||value(id,l)!==null);const unknown=playableIds(l.mine).filter(id=>value(id,l)===null);return analysisHeader('Start / sit','Your best legal lineup, with room for a late swap.')+`${unknown.length?`<div class="note warn">${unknown.length} rostered player(s) have no projection. Review them before following the optimizer.</div>`:''}<div class="panel decision"><div><div class="eyebrow">PROJECTED LINEUP IMPROVEMENT</div><h2>${complete?`${signed(best.total-baseline)} points`:'Partial lineup estimate'}</h2><p class="muted small">${Object.keys(locks).length} started slots locked · injured players excluded · legal flex assignments</p></div><div><div class="big-number">${best.complete?fmt(best.total):'—'}</div><div class="muted small">optimized projection</div></div></div><div class="panel table-wrap"><table><thead><tr><th>SLOT</th><th>CURRENT STARTER</th><th>RECOMMENDED</th><th>PROJECTION</th><th>DECISION</th></tr></thead><tbody>${slots.map((s,i)=>{const id=best.ids[i],same=id===ids[i],lock=i in locks;return `<tr><td><strong>${esc(s)}</strong></td><td>${esc(pname(ids[i]))}</td><td><strong>${esc(pname(id))}</strong>${id?`<div class="small muted">${esc(data.players[id]?.team||'FA')} · ${esc(data.players[id]?.position)}</div>`:''}</td><td class="num">${id?fmt(value(id,l)):'—'}</td><td><span class="pill ${!same&&!lock&&id?'live':''}">${lock?'LOCKED':same?'KEEP':id?'SWAP IN':'NO PROJECTION'}</span></td></tr>`}).join('')}</tbody></table></div><p class="muted small">Uses expected points. Live-game projections are pregame estimates, not predicted final scores. Make lineup changes in Sleeper.</p>${!data.demo?`<a class="secondary" href="https://sleeper.com/leagues/${esc(l.league_id)}/team" target="_blank" rel="noopener">Open league in Sleeper ↗</a>`:''}`;}
function waiverRows(){const l=league(),owned=new Set(l.rosters.flatMap(r=>[...(r.players||[]),...(r.reserve||[]),...(r.taxi||[])])),trending=new Map(data.trends.map(t=>[t.player_id,t.count])),free=availableIds(l,data.players).filter(id=>['QB','RB','WR','TE','K','DEF'].includes(data.players[id].position)&&(position==='ALL'||data.players[id].position===position));const roster=playableIds(l.mine),slots=activeSlots(l),{locks}=lockedLineup(l),fixed=Object.values(locks),v=id=>usableValue(id,l,fixed);let base;try{base=optimize(roster,slots,data.players,v,locks)}catch{return []}const candidates=[...new Set([...free.filter(id=>trending.has(id)).sort((a,b)=>trending.get(b)-trending.get(a)).slice(0,30),...free.filter(id=>value(id,l)!==null).sort((a,b)=>value(b,l)-value(a,l)).slice(0,25)])];const drops=roster.filter(id=>!fixed.includes(id)).sort((a,b)=>(value(a,l)??-1)-(value(b,l)??-1)).slice(0,8);return candidates.map(id=>{let best=null;for(const drop of (roster.length<l.roster_positions.length?[null]:drops)){const result=optimize(roster.filter(x=>x!==drop).concat(id),slots,data.players,v,locks);const gain=result.total-base.total;if(!best||gain>best.gain)best={drop,gain,complete:result.complete&&base.complete}}return {id,count:trending.get(id)||0,projection:value(id,l),...best,gain:best?.complete&&v(id)!==null?best.gain:null};}).sort((a,b)=>(b.gain??-999)-(a.gain??-999)||b.count-a.count).slice(0,20);}
function waivers(){const l=league(),rows=waiverRows();return analysisHeader('Waiver wire','Available in your league. Ranked for your roster.')+`<div class="section-bar"><h2>Find your next advantage</h2><select class="select" id="position" aria-label="Player position">${['ALL','QB','RB','WR','TE','K','DEF'].map(p=>`<option ${p===position?'selected':''} value="${p}">${p==='ALL'?'All positions':p}</option>`).join('')}</select></div><div class="panel table-wrap"><table><thead><tr><th>PLAYER</th><th>ADDS / 24H</th><th>PROJ.</th><th>LINEUP GAIN</th><th>SUGGESTED DROP</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(pname(r.id))}</strong><div class="muted small">${esc(data.players[r.id].team||'FA')} · ${esc(data.players[r.id].position)}${data.players[r.id].injury_status?' · '+esc(data.players[r.id].injury_status):''}</div></td><td>${r.count?r.count.toLocaleString():'—'}</td><td>${fmt(r.projection)}</td><td class="${r.gain>0?'gain':'muted'}">${r.gain===null?'Unavailable':signed(r.gain)}</td><td>${r.drop?esc(pname(r.drop)):'Open roster spot'}</td><td><button class="pin ${pins.has(r.id)?'on':''}" data-pin="${esc(r.id)}" aria-label="Watch ${esc(pname(r.id))}">${pins.has(r.id)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table>${!rows.length?empty('No available players match','Try another position or refresh league data.'):''}</div><div class="note">Gain compares your optimized lineup before and after a pickup. A player whose game started may be a future stash, but cannot improve this week’s lineup. Review depth before dropping anyone.</div><div class="panel"><h3>Waiver budget</h3><p class="muted">${l.settings?.waiver_budget?`${Math.max(0,l.settings.waiver_budget-(l.mine.settings?.waiver_budget_used||0))} of ${l.settings.waiver_budget} remaining. Bid recommendations need league bidding history; this prototype does not guess them.`:'This league uses waiver priority or has no budget available.'} Global adds are provided by Sleeper.</p></div>`;}
function partners(l){return l.rosters.filter(r=>r.roster_id!==l.mine.roster_id)}
function partnerName(l,r){const u=l.users.find(u=>u.user_id===r.owner_id);return u?.metadata?.team_name||u?.display_name||'Team '+r.roster_id}
function tradeInput(l){const partner=partners(l).find(r=>String(r.roster_id)===partnerId)||partners(l)[0];if(partner)partnerId=String(partner.roster_id);return partner;}
function tradeEval(l,p,giveIds,getIds,freeAgents=null){return tradeResult({league:l,roster:l.mine,partner:p,give:giveIds,get:getIds,players:data.players,value:id=>value(id,l),freeAgents:freeAgents||availableIds(l,data.players).filter(id=>value(id,l)!==null).sort((a,b)=>value(b,l)-value(a,l))});}
function tradeSummary(r,title='Trade impact'){return `<div class="panel"><div class="decision"><div><div class="eyebrow">${title}</div><h3>${r.give.map(id=>esc(pname(id))).join(' + ')} <span class="muted">for</span> ${r.get.map(id=>esc(pname(id))).join(' + ')}</h3><p class="muted small">${esc(r.partner||'Selected partner')} · week ${data.week} optimized starters</p></div><div class="decision-score ${r.gainA>0?'gain':'loss'}">${signed(r.gainA)}<div class="small muted">your points</div></div></div><div class="badge-line"><span>Their gain: ${signed(r.gainB)}</span><span>Your weighted score: ${signed(r.gainA-penalty*Math.max(0,r.gainB))}</span><span>${r.complete?'Full lineups modeled':'Incomplete projections'}</span></div>${r.addedA.length?`<p class="small muted" style="margin-top:12px">Also assumes you add ${r.addedA.map(id=>esc(pname(id))).join(', ')} from waivers.</p>`:''}${r.addedB.length?`<p class="small muted">Assumes they add ${r.addedB.map(id=>esc(pname(id))).join(', ')} from waivers.</p>`:''}${r.droppedA.length||r.droppedB.length?`<p class="small attention">Required drops: you — ${r.droppedA.map(pname).join(', ')||'none'}; them — ${r.droppedB.map(pname).join(', ')||'none'}.</p>`:''}</div>`}
function trades(){const l=league(),p=tradeInput(l);return analysisHeader('Trade lab','Find deals that make your starting lineup better.')+`<div class="note">Prototype scope: player trades and this week’s pregame projections. Already-started players cannot deliver these gains this week. It does not value draft picks, keeper cost, or rest-of-season upside.${l.settings?.type===2?' <strong>Dynasty league: this is only a short-term lineup comparison, not a dynasty trade valuation.</strong>':''} Trades are hypothetical and never sent automatically.</div><div class="panel"><div class="section-bar"><h2>Your advantage, your rules</h2><button class="primary" id="suggest-trades">Find trade ideas →</button></div><div class="trade-controls"><label for="penalty">Penalty for helping a rival <strong id="penalty-label">${Math.round(penalty*100)}%</strong></label><input id="penalty" type="range" min="0" max="100" step="5" value="${penalty*100}"><label class="checkline"><input type="checkbox" id="require-benefit" ${requireBenefit?'checked':''}>Only ideas that also improve their lineup</label></div><p class="muted small">Your gain − ${penalty.toFixed(2)} × their positive gain. Your benefit stays primary, even when they gain more.</p></div>${tradeSuggestions===null?'':tradeSuggestions.length?tradeSuggestions.map(r=>tradeSummary(r,'SUGGESTED OFFER')).join(''):empty('No qualifying trades found','Try lowering the rival penalty or allowing trades without an immediate benefit for the other team.')}<div class="section-bar" style="margin-top:25px"><h2>Build your own trade</h2><select class="select" id="trade-partner" aria-label="Trade partner">${partners(l).map(r=>`<option value="${r.roster_id}" ${String(r.roster_id)===partnerId?'selected':''}>${esc(partnerName(l,r))}</option>`).join('')}</select></div>${p?`<div class="split">${[[l.mine,'You send',give,'give'],[p,'You receive',get,'get']].map(([r,title,selected,type])=>`<div class="panel"><h3>${title}</h3><div class="trade-picks">${playableIds(r).map(id=>`<label class="list-choice"><span class="checkline"><input type="checkbox" data-trade="${type}" value="${esc(id)}" ${selected.includes(id)?'checked':''}>${esc(pname(id))}</span><span class="muted small">${esc(data.players[id]?.position)} · ${fmt(value(id,l))}</span></label>`).join('')}</div></div>`).join('')}</div><button class="primary" id="analyze-trade">Analyze trade</button>${tradeManual?`<div style="margin-top:20px">${tradeSummary(tradeManual)}</div>`:''}`:empty('No trading partners found')}`;}
function defenses(){const l=league();if(!activeSlots(l).includes('DEF'))return analysisHeader('Defense planner','A good matchup today. A better plan for next Sunday.')+empty('This league does not start team defenses','Select a league with a DEF slot.');const own=playableIds(l.mine).filter(id=>data.players[id]?.position==='DEF'),free=availableIds(l,data.players).filter(id=>data.players[id].position==='DEF'),weeks=[data.week,data.week+1,data.week+2].filter(w=>w<=18),rank=[...new Set([...own,...free])].map(id=>({id,vals:weeks.map(w=>value(id,l,w))})).sort((a,b)=>b.vals.reduce((s,v)=>s+(v??0),0)-a.vals.reduce((s,v)=>s+(v??0),0));let bestPair=null;for(const a of rank)for(const b of rank){if(a.id>=b.id||[...a.vals,...b.vals].some(x=>x===null))continue;const total=a.vals.reduce((s,v,i)=>s+Math.max(v,b.vals[i]),0);if(!bestPair||total>bestPair.total)bestPair={a,b,total}}const bestSingle=rank.filter(r=>r.vals.every(v=>v!==null)).sort((a,b)=>b.vals.reduce((s,v)=>s+v,0)-a.vals.reduce((s,v)=>s+v,0))[0];return analysisHeader('Defense planner','A good matchup today. A better plan for next Sunday.')+`${bestPair&&bestSingle?`<div class="panel decision"><div><div class="eyebrow">BEST TWO-DEFENSE ROTATION</div><h2>${esc(bestPair.a.id)} + ${esc(bestPair.b.id)}</h2><p class="muted small">${weeks.map((w,i)=>`Week ${w}: ${bestPair.a.vals[i]>=bestPair.b.vals[i]?bestPair.a.id:bestPair.b.id}`).join(' · ')}</p></div><div><div class="big-number gain">${signed(bestPair.total-bestSingle.vals.reduce((s,v)=>s+v,0))}</div><div class="muted small">over best single defense</div></div></div>`:'<div class="note warn">A rotation needs projections for all three weeks. Available weeks are shown below.</div>'}<div class="panel table-wrap"><table class="week-table"><thead><tr><th>DEFENSE</th>${weeks.map(w=>`<th>WEEK ${w}</th>`).join('')}<th>AVAILABILITY</th></tr></thead><tbody>${rank.map(r=>`<tr><td><strong>${esc(pname(r.id))}</strong></td>${weeks.map((w,i)=>{const p=data.projections[w]?.[r.id],g=data.schedules[w]?.[r.id];return `<td><strong>${fmt(r.vals[i])}</strong><div class="small muted">${p?.opponent?'vs '+esc(p.opponent):g?'vs '+esc(g.opponent):'Schedule unavailable'}</div></td>`}).join('')}<td><span class="pill ${own.includes(r.id)?'live':''}">${own.includes(r.id)?'ON YOUR TEAM':'AVAILABLE'}</span></td></tr>`).join('')}</tbody></table></div><div class="note">A second defense costs a bench spot. The rotation gain does not subtract the value of the player you’d drop, waiver costs, or pickup restrictions. This is a planning comparison; check those costs before making a move.</div>`;}
function settings(){return pageHead('My leagues','One account. Every team you care about.',`<button class="primary" data-connect>${data.demo?'Connect Sleeper':'Switch account'}</button>`)+`<div class="panel"><div class="section-bar"><div><h2 style="margin-bottom:6px">${data.demo?'Explore three sample leagues':esc(data.user.username)}</h2><p class="muted small">Choose which leagues appear in your watchroom and analysis.</p></div><span class="pill ${data.demo?'demo':'live'}">${data.demo?'SAMPLE DATA':'CONNECTED'}</span></div>${data.leagues.map((l,i)=>`<label class="league-settings"><input type="checkbox" data-league-toggle="${esc(l.league_id)}" ${l.enabled?'checked':''}><div style="flex:1"><strong>${esc(l.name)}</strong><div class="muted small">${scoring(l)} · ${l.rosters.length} teams · ${l.settings?.type===2?'Dynasty':l.settings?.type===1?'Keeper':'Redraft'}</div></div>${!data.demo?`<a href="https://sleeper.com/leagues/${esc(l.league_id)}" target="_blank" rel="noopener" class="link-external">Open ↗</a>`:''}</label>`).join('')}</div><div class="split"><div class="panel"><h3>Made for Sunday</h3><p class="muted small">Pin players for quick scanning. Use Focus mode for a larger watchroom. Include opponents to spot players who help one team and hurt another.</p></div><div class="panel"><h3>About your data</h3><p class="muted small">Public Sleeper data is read-only. Scores refresh every 45 seconds while this tab is visible; they may trail the broadcast. NFL game status comes from ESPN. Player details are cached for 24 hours.</p></div></div><div class="panel"><h3>Prototype limits</h3><p class="muted small">Projection access is experimental and can change. Advice uses expected points, not a calibrated win probability. Advanced bonuses, dynasty values, FAAB bids, alerts, and season-long trade modeling are not yet included. “Unavailable” never means zero.</p></div>${!data.demo?'<button class="secondary disconnect" id="disconnect">Disconnect and return to demo</button>':''}`;}
async function connect(username){const run=++connectRun,button=$('#connect-form button[type=submit]');button.disabled=true;button.textContent='Finding your leagues…';$('#connect-error').textContent='';try{const found=await api.discover(username),week=Math.max(1,Math.min(18,Number(found.nfl.week)||1));const [players,details]=await Promise.all([api.loadPlayers(),Promise.allSettled(found.leagues.map(l=>api.leagueDetails(l,found.user.user_id,week)))]);if(run!==connectRun)return;const leagues=details.filter(r=>r.status==='fulfilled').map(r=>({...r.value,enabled:!(prefs.disabled||[]).includes(r.value.league_id)&&r.value.status!=='complete'}));if(!leagues.length)throw Error('No leagues could be loaded. Please refresh and try again.');if(!leagues.some(l=>l.enabled))leagues.forEach(l=>l.enabled=true);data={user:found.user,nfl:found.nfl,week,players,leagues,projections:{},games:{},schedules:{},trends:[],updatedAt:Date.now(),demo:false,errors:details.flatMap((r,i)=>r.status==='rejected'?[`Could not load ${found.leagues[i].name}.`]:[])};leagueId=leagues[0].league_id;watchLeague='all';give=[];get=[];tradeManual=null;tradeSuggestions=null;prefs.username=found.user.username;savePrefs();$('#connect').close();render();await refresh(true);toast(`Connected ${leagues.length} league${leagues.length===1?'':'s'}.`);}catch(e){if(run===connectRun){$('#connect-error').textContent=e.message;if(!$('#connect').open)toast('Could not reconnect: '+e.message)}}finally{button.disabled=false;button.textContent='Find my leagues →';}}
async function refresh(full=false){if(busy||data.demo){if(data.demo)toast('Demo scores are illustrative. Connect Sleeper for live updates.');return}busy=true;render();const current=data,userId=data.user.user_id,week=data.week;const requests=[...data.leagues.map(l=>api.leagueDetails(l,userId,week)),api.scoreboard(data.nfl.season,week)];if(full){for(let w=week;w<=Math.min(18,week+2);w++)requests.push(api.projections(data.nfl.season,w));requests.push(api.trends());}const results=await Promise.allSettled(requests);if(current!==data){busy=false;return}const errors=[];const n=data.leagues.length;results.slice(0,n).forEach((r,i)=>{if(r.status==='fulfilled')data.leagues[i]={...r.value,enabled:data.leagues[i].enabled};else errors.push(`${data.leagues[i].name}: refresh failed; showing previous scores.`)});if(results[n].status==='fulfilled'){data.games=results[n].value;data.schedules[week]=data.games}else errors.push('NFL game status unavailable; previous status may be stale.');if(full){for(let i=n+1;i<results.length-1;i++){const w=week+i-n-1;if(results[i].status==='fulfilled')data.projections[w]=results[i].value;else{delete data.projections[w];errors.push(`Week ${w} projections unavailable.`)}}const t=results.at(-1);if(t.status==='fulfilled')data.trends=t.value;else errors.push('Trending adds are unavailable.')}data.errors=errors;if(results.slice(0,n).some(r=>r.status==='fulfilled'))data.updatedAt=Date.now();busy=false;render();}
async function suggestTrades(){const l=league();if(!Object.keys(data.projections[data.week]||{}).length){toast('Projections are required to generate trades.');return}const btn=$('#suggest-trades');btn.disabled=true;btn.textContent='Comparing rosters…';await new Promise(r=>setTimeout(r,20));try{const ideas=[],free=availableIds(l,data.players).filter(id=>value(id,l)!==null).sort((a,b)=>value(b,l)-value(a,l)),own=playableIds(l.mine).filter(id=>value(id,l)!==null&&data.players[id]?.position!=='DEF').sort((a,b)=>value(b,l)-value(a,l)).slice(0,12);for(const p of partners(l)){const theirs=playableIds(p).filter(id=>value(id,l)!==null&&data.players[id]?.position!=='DEF').sort((a,b)=>value(b,l)-value(a,l)).slice(0,12);for(const a of own)for(const b of theirs){const r=tradeEval(l,p,[a],[b],free);if(r.complete&&r.gainA>.25&&(!requireBenefit||r.gainB>.1))ideas.push({...r,give:[a],get:[b],partner:partnerName(l,p)})}await new Promise(r=>setTimeout(r,0));}tradeSuggestions=ideas.sort((a,b)=>(b.gainA-penalty*Math.max(0,b.gainB))-(a.gainA-penalty*Math.max(0,a.gainB))).slice(0,5);render()}catch(e){toast(e.message);render()}}
document.addEventListener('click',e=>{const t=e.target;const n=t.closest('[data-nav]');if(n){view=n.dataset.nav;render();window.scrollTo({top:0});return}if(t.closest('[data-connect]')){$('#username').value=prefs.username||'';$('#connect-error').textContent='';$('#connect').showModal();$('#username').focus()}if(t.closest('#cancel-connect')){connectRun++;$('#connect').close()}if(t.closest('#focus')){focus=!focus;render()}const f=t.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}const p=t.closest('[data-pin]');if(p){pins.has(p.dataset.pin)?pins.delete(p.dataset.pin):pins.add(p.dataset.pin);savePrefs();render()}if(t.closest('#refresh'))refresh(true);if(t.closest('#disconnect')){connectRun++;prefs.username=null;prefs.disabled=[];data=demo();leagueId=data.leagues[0].league_id;watchLeague='all';give=[];get=[];tradeManual=null;tradeSuggestions=null;savePrefs();render();toast('Disconnected. Sample data is now displayed.')}if(t.closest('#suggest-trades'))suggestTrades();if(t.closest('#analyze-trade')){const l=league(),p=tradeInput(l);try{if([...give,...get].some(id=>value(id,l)===null))throw Error('Every selected player needs a projection before this trade can be evaluated.');const r=tradeEval(l,p,give,get);tradeManual={...r,give:[...give],get:[...get],partner:partnerName(l,p)};render()}catch(e){toast(e.message)}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){query=t.value;$('#players').innerHTML=watchCards()}if(t.id==='penalty'){penalty=Number(t.value)/100;$('#penalty-label').textContent=Math.round(penalty*100)+'%'}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='analysis-league'){leagueId=t.value;give=[];get=[];tradeSuggestions=null;tradeManual=null;render()}if(t.id==='watch-league'){watchLeague=t.value;render()}if(t.id==='watch-role'){watchRole=t.value;render()}if(t.id==='bench'){bench=t.checked;render()}if(t.id==='position'){position=t.value;render()}if(t.id==='trade-partner'){partnerId=t.value;get=[];tradeManual=null;render()}if(t.id==='require-benefit'){requireBenefit=t.checked;tradeSuggestions=null;render()}if(t.id==='penalty'){if(tradeSuggestions)tradeSuggestions.sort((a,b)=>(b.gainA-penalty*Math.max(0,b.gainB))-(a.gainA-penalty*Math.max(0,a.gainB)));render()}if(t.dataset.trade){let list=t.dataset.trade==='give'?give:get;list=t.checked?[...list,t.value]:list.filter(id=>id!==t.value);if(t.dataset.trade==='give')give=list;else get=list;tradeManual=null}if(t.dataset.leagueToggle){const l=data.leagues.find(l=>l.league_id===t.dataset.leagueToggle);l.enabled=t.checked;watchLeague='all';tradeSuggestions=null;tradeManual=null;savePrefs();render()}if(t.id==='week'){const week=Number(t.value);if(data.demo){toast('The demo illustrates Week 2. Connect Sleeper to browse other weeks.');render();return}if(busy){toast('Wait for the current refresh to finish.');render();return}data.week=week;data.games={};data.leagues=data.leagues.map(l=>({...l,matchups:[]}));tradeSuggestions=null;tradeManual=null;await refresh(true)}});
$('#connect-form').addEventListener('submit',e=>{e.preventDefault();const u=$('#username').value.trim();if(u)connect(u)});$('#connect').addEventListener('cancel',()=>connectRun++);
setInterval(()=>{if(!document.hidden&&!data.demo)refresh(false)},45000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!data.demo&&Date.now()-data.updatedAt>45000)refresh(false)});
render();
if(prefs.username){$('#username').value=prefs.username;connect(prefs.username)}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_sunday_watchroom',description:'Read tracked fantasy players, league-specific points, and game status currently available in Sunday.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(Object.keys(input||{}).length)throw Error('This tool takes no arguments.');return {demo:data.demo,week:data.week,updatedAt:data.updatedAt,players:aggregateWatch(data.leagues,data.players,data.games).map(p=>({name:pname(p.id),number:p.player.number,team:p.player.team,status:p.game?.state||'unknown',leagues:p.appearances}))}}})}catch{}}
